$titulo_pagina='Minhas Publicações';$estilos_pagina=['/assets/css/admin.css?v=5'];require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/functions.php';verificarProfissional();$perfil=pegar_perfil_profissional_por_usuario($_SESSION['usuario_id']);if(!$perfil)redirecionar('/dashboard/profissional.php');$erros=[];
if($_SERVER['REQUEST_METHOD']==='POST'){if(!validar_csrf($_POST['csrf_token']??''))$erros[]='Sessão expirada.';$conteudo=trim($_POST['conteudo']??'');$imagem=trim($_POST['imagem_url']??'');$tags=implode(' ',array_slice(array_filter(array_map(fn($t)=>'#'.preg_replace('/[^\pL\pN_]/u','',ltrim(trim($t),'#')),preg_split('/[,\s]+/',$_POST['tags']??''))),0,10));if(!empty($_FILES['imagem']['name'])){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['imagem']['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($ext[$mime]))$erros[]='Imagem inválida.';else{$dir=__DIR__.'/../assets/uploads/posts';if(!is_dir($dir))mkdir($dir,0755,true);$file=bin2hex(random_bytes(16)).'.'.$ext[$mime];if(move_uploaded_file($_FILES['imagem']['tmp_name'],$dir.'/'.$file))$imagem='/assets/uploads/posts/'.$file;}}if(mb_strlen($conteudo)<3)$erros[]='Escreva uma publicação.';if($imagem&&!str_starts_with($imagem,'/assets/uploads/')&&!filter_var($imagem,FILTER_VALIDATE_URL))$erros[]='URL inválida.';if(!$erros){$stmt=$mysqli->prepare('INSERT INTO publicacoes_profissionais(profissional_id,conteudo,imagem_url,tags) VALUES(?,?,?,?)');$stmt->bind_param('isss',$perfil['id'],$conteudo,$imagem,$tags);$stmt->execute();mensagem_sucesso('Publicado no feed e no seu perfil.');redirecionar('/dashboard/feed.php');}}
